<?php
class DisciplineController {private $m;public function __construct(){if(!isStaffAdmin())redirect('login');$this->m=new HrSuite();}
 public function review($id){require_capability('discipline.review');$this->post();$r=$this->row($id);if($r&&$r->workflow_status==='draft'){$hash=hash('sha256',json_encode([$r->id,$r->user_id,$r->title,$r->description,$r->incident_date],JSON_UNESCAPED_UNICODE));$this->m->execute("UPDATE employee_incidents SET workflow_status='reviewed',reviewed_by=?,reviewed_at=NOW(),document_hash=? WHERE id=?",[(int)$_SESSION['user_id'],$hash,$id]);$this->m->audit()->record('discipline.reviewed','employee_incident',$id,['status'=>'draft'],['status'=>'reviewed','hash'=>$hash],trim($_POST['reason']??''),adminCompanyId());}redirect('admin/employeeProfile/'.($r->user_id??0).'#tab-incidents');}
 public function notify($id){require_capability('discipline.review');$this->post();$r=$this->row($id);if($r&&$r->workflow_status==='reviewed'){$this->m->execute("UPDATE employee_incidents SET workflow_status='notified',notified_at=NOW() WHERE id=?",[$id]);$this->m->audit()->record('discipline.notified','employee_incident',$id,['status'=>'reviewed'],['status'=>'notified'],'',adminCompanyId());}redirect('admin/employeeProfile/'.($r->user_id??0).'#tab-incidents');}
 public function void($id){require_capability('discipline.review');$this->post();$r=$this->row($id);$reason=trim($_POST['reason']??'');if($r&&$reason!==''){$this->m->execute("UPDATE employee_incidents SET workflow_status='void',void_reason=? WHERE id=?",[$reason,$id]);$this->m->audit()->record('discipline.voided','employee_incident',$id,['status'=>$r->workflow_status],['status'=>'void'],$reason,adminCompanyId());}redirect('admin/employeeProfile/'.($r->user_id??0).'#tab-incidents');}
 private function row($id){return $this->m->one('SELECT ei.* FROM employee_incidents ei JOIN users u ON u.id=ei.user_id WHERE ei.id=? AND u.company_id=?',[(int)$id,adminCompanyId()]);}private function post(){if($_SERVER['REQUEST_METHOD']!=='POST')redirect('admin/dashboard');csrf_verify();}}
